sys.path.insert(0,'/scr/wurgaft/auto-psych/agent_trees/043c9ecd8d452a7b/repo/_runs/cell_1/experiment1/model_loop/models')
import bigelow_piantadosi_mixture as B
from scipy.special import logsumexp
rows=list(csv.DictReader(open('/scr/wurgaft/auto-psych/agent_trees/043c9ecd8d452a7b/repo/_runs/cell_1/experiment1/model_loop/responses.csv')))
y=np.array([int(r['rating']) for r in rows]); print('yes rate',y.mean(), len(set(r['number_set'] for r in rows)))
sets=[tuple(int(x) for x in r['number_set'].split(',')) for r in rows]; t=np.array([int(r['target'])-1 for r in rows])
