    prior=np.r_[np.full(B.N_RULES,np.log(lam/B.N_RULES)), np.full(len(M)-B.N_RULES,np.log((1-lam)/1e4))]
    tot=0;cache={}
    p=np.empty(len(rows))
    for i,(s,tt) in enumerate(zip(sets,t)):
        if s not in cache:
            lj=prior+beta*E[:,np.array(s)-1].sum(1); post=np.exp(lj-logsumexp(lj)); cache[s]=post@M
        p[i]=cache[s][tt]
    p=np.clip(eps+(1-2*eps)*p**gam,1e-9,1-1e-9)
    return (y*np.log(p)+(1-y)*np.log(1-p)).sum()
for lam in [.3,.5,.7,.9]: print('base',lam,ll(lam))
